#ifndef CSM_INVENTORY_H
#define CSM_INVENTORY_H

#include <stddef.h>
#include <time.h>

enum dir_state {
	STATE_ACTIVE,		/* the project path exists */
	STATE_ORPHAN,		/* the project path is gone */
	STATE_UNAVAILABLE,	/* cannot tell: no access, volume not mounted */
	STATE_UNKNOWN		/* no session file gives the project path */
};

/* One session directory, as csm -l shows it. */
struct session_dir_info {
	char *name;
	char *path;
	char *project;		/* NULL when unknown */
	enum dir_state state;
	size_t sessions;	/* top-level <uuid>.jsonl files */
	unsigned long long size;	/* bytes in regular files */
	time_t modified;	/* newest file, else the directory */
};

struct inventory {
	struct session_dir_info *dirs;
	size_t count;
};

enum dir_state path_state(const char *path, const char *const *mount_parents);
const char *state_name(enum dir_state state);
void inventory_walk(const char *dir, unsigned long long *size,
    time_t *newest, int *any);
void inventory_read_dir(const char *path, struct session_dir_info *info);
int inventory_scan(const char *projects_dir, struct inventory *inv);
size_t inventory_match(const struct inventory *inv, const char *arg,
    size_t *found);
void inventory_free(struct inventory *inv);

#endif
